GREEN=colors.HexColor('#124e43'); GOLD=colors.HexColor('#edb63e'); CREAM=colors.HexColor('#fff7df'); RED=colors.HexColor('#9e3341'); GRAY=colors.HexColor('#53665f')
styles=getSampleStyleSheet()
